Servo.example:
#include <ESP32Servo.h>
Servo myservo;
void setup() {
  myservo.setPeriodHertz(50);   // standard 50 Hz servo
  myservo.attach(18, 500, 2400); // pin, min us, max us
  myservo.write(90);            // center
}

attach.example:
myservo.attach(18);
// or with explicit pulse range:
myservo.attach(18, 500, 2400);
